package dev.utherhel.attributification.selftest;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/**
 * PASS/FAIL records of one side of a self-test run, written as &lt;out&gt;/&lt;side&gt;.json for dev/modtest.
 * Generated by dev/modtest/sync.py from the shared template; edit the template, not this copy.
 */
public final class Report {
    private final String side;
    private final List<String> entries = new ArrayList<>();
    private int passed, failed;

    Report(String side) {
        this.side = side;
    }

    public void record(String name, boolean pass, String detail) {
        String d = detail == null ? "" : detail;
        entries.add("{\"name\":" + quote(name) + ",\"pass\":" + pass + ",\"detail\":" + quote(d) + "}");
        if (pass) passed++;
        else failed++;
        System.out.println("[ModTest] " + (pass ? "PASS " : "FAIL ") + side + "/" + name + "  " + d);
    }

    public int failed() {
        return failed;
    }

    void write(String out, String mode) {
        String json = "{\"mod\":" + quote(SelfTest.ID) + ",\"version\":" + quote(ModTestHook.version(SelfTest.ID))
            + ",\"loader\":" + quote(ModTestHook.loader()) + ",\"mc\":" + quote(TestCompat.versionName())
            + ",\"side\":" + quote(side) + ",\"mode\":" + quote(mode) + ",\"passed\":" + passed + ",\"failed\":" + failed
            + ",\"results\":[" + String.join(",", entries) + "]}\n";
        try {
            Path dir = Path.of(out);
            Files.createDirectories(dir);
            Path tmp = dir.resolve(side + ".json.tmp");
            Files.writeString(tmp, json, StandardCharsets.UTF_8);
            Files.move(tmp, dir.resolve(side + ".json"), java.nio.file.StandardCopyOption.REPLACE_EXISTING);
        } catch (IOException e) {
            System.out.println("[ModTest] could not write results: " + e);
        }
        System.out.println("[ModTest] " + side + " done: " + passed + " passed, " + failed + " failed");
    }

    static String quote(String s) {
        StringBuilder b = new StringBuilder("\"");
        for (char c : s.toCharArray()) {
            switch (c) {
                case '"' -> b.append("\\\"");
                case '\\' -> b.append("\\\\");
                case '\n' -> b.append("\\n");
                case '\r' -> b.append("\\r");
                case '\t' -> b.append("\\t");
                default -> {
                    if (c < 0x20) b.append(String.format("\\u%04x", (int) c));
                    else b.append(c);
                }
            }
        }
        return b.append('"').toString();
    }

    static String describe(Throwable t) {
        StringBuilder b = new StringBuilder(t.toString());
        StackTraceElement[] st = t.getStackTrace();
        for (int i = 0; i < Math.min(4, st.length); i++) b.append(" @ ").append(st[i]);
        return b.toString();
    }
}
